    try:
        return _perceive_impl(observation_history)
    except Exception:
        return "step=0; PARSE_ERROR; sig=none"

def _perceive_impl(observation_history: List[str]) -> str:
    if not observation_history:
        return "step=0; EMPTY_HISTORY"

    step = len(observation_history)  # true step counter
    obs = observation_history[-1]
    grid = _parse_grid(obs)
    if grid is None:
        return f"step={step}; PARSE_ERROR; sig={_grid_signature(obs)}"

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    if rows == 0 or cols == 0:
        return f"step={step}; EMPTY_GRID rows={rows} cols={cols}"

    # Determine background colour
    all_colours = [cell for row in grid for cell in row]
    bg = Counter(all_colours).most_common(1)[0][0]

    # Current objects map for compact description
    cur_desc = _describe_grid(grid, bg)
    signature = _grid_signature(obs)
    stats = _colour_stats(grid, bg)

    # Build the output parts
    parts = [f"step={step}; rows={rows} cols={cols} bg:{bg}; sig:{signature}; {stats}"]

    # If we have a previous observation, compute delta and include it
    if len(observation_history) >= 2:
        prev_obs = observation_history[-2]
        prev_grid = _parse_grid(prev_obs)
        if prev_grid is not None:
            prev_objects = []
            cur_objects = []
            for r, row in enumerate(grid):
                for c, colour in enumerate(row):
                    if colour != bg:
                        cur_objects.append((r, c, colour))
            for r, row in enumerate(prev_grid):
                for c, colour in enumerate(row):
                    if colour != bg:
                        prev_objects.append((r, c, colour))
            delta_str = _compute_delta(prev_objects, cur_objects)
            parts.append(f"delta:{delta_str}")

    # Append the full current description (compact coordinate list)
    if cur_desc:
        parts.append("cells:" + cur_desc)
    else:
        parts.append("cells:empty")

    result = "; ".join(parts)
    if len(result) > 1999:
        # Remove delta if present, then truncate
        if "delta:" in result:
            parts_no_delta = [p for p in parts if not p.startswith("delta:")]
            result = "; ".join(parts_no_delta)
        if len(result) > 1999:
            result = result[:1996] + "..."
    return result

import json
import hashlib
from collections import Counter
from typing import List, Tuple, Optional, Dict, Set

def _parse_grid(obs: str) -> Optional[List[List[str]]]:
    """Extract the 2D colour grid as list[list[str]]."""
    if not obs:
        return None
    start = obs.find("[[")
    end = obs.rfind("]]")
    if start == -1 or end == -1 or end < start:
        return None
    try:
        grid = json.loads(obs[start:end+2])
    except Exception:
        return None
    if not grid or not isinstance(grid, list) or not isinstance(grid[0], list):
        return None
    return grid

def _grid_signature(obs: str) -> str:
    """Return a short hash of the raw observation to uniquely identify the state."""
    return hashlib.md5(obs.encode()).hexdigest()[:8]

def _describe_grid(grid: List[List[str]], bg: str) -> str:
    """
    Build a compact string describing all non‑background cells.
    Format:  colour:(r,c)(r,c)...  (no spaces, sorted by row then col)
    """
    objects = []
    for r, row in enumerate(grid):
        for c, colour in enumerate(row):
            if colour != bg:
                objects.append((r, c, colour))
    by_colour: Dict[str, List[Tuple[int, int]]] = {}
    for r, c, colour in objects:
        by_colour.setdefault(colour, []).append((r, c))
    parts = []
    for colour in sorted(by_colour.keys()):
        cells = by_colour[colour]
        cells.sort(key=lambda x: (x[0], x[1]))
        cell_str = "".join(f"({r},{c})" for r, c in cells)
        parts.append(f"{colour}:{cell_str}")
    return "|".join(parts)

def _colour_stats(grid: List[List[str]], bg: str) -> str:
    """
    Return a compact flag string highlighting boundary conditions for each colour.
    E.g., "red:bottom|green:top" if red touches bottom or green touches top.
    """
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    flags_parts = []
    # gather per‑colour min/max row
    colour_rows: Dict[str, Set[int]] = {}
    for r, row in enumerate(grid):
        for c, colour in enumerate(row):
            if colour != bg:
                colour_rows.setdefault(colour, set()).add(r)
    for colour in sorted(colour_rows.keys()):
        min_r = min(colour_rows[colour])
        max_r = max(colour_rows[colour])
        if max_r == rows - 1:
            flags_parts.append(f"{colour}:bottom")
        if min_r == 0:
            flags_parts.append(f"{colour}:top")
    if not flags_parts:
        return "flags:none"
    return "flags:" + "|".join(flags_parts)

def _compute_delta(prev_objects: List[Tuple[int,int,str]],
                   cur_objects: List[Tuple[int,int,str]]) -> str:
    """
    Given two lists of (r,c,color) for the same colours, compute a compact string
    describing how each colour moved or changed.
    """
    prev_map: Dict[str, Set[Tuple[int,int]]] = {}
    cur_map: Dict[str, Set[Tuple[int,int]]] = {}
    for r,c,colour in prev_objects:
        prev_map.setdefault(colour, set()).add((r,c))
    for r,c,colour in cur_objects:
        cur_map.setdefault(colour, set()).add((r,c))

    deltas = []
    all_colours = set(prev_map.keys()) | set(cur_map.keys())
    for colour in sorted(all_colours):
        prev_set = prev_map.get(colour, set())
        cur_set = cur_map.get(colour, set())
        if prev_set == cur_set:
            continue
        # Try to detect a simple translation (all cells shift by same (dr,dc))
        if prev_set and cur_set and len(prev_set) == len(cur_set):
            p = next(iter(prev_set))
            c = next(iter(cur_set))
            dr = c[0] - p[0]
            dc = c[1] - p[1]
            shifted = {(p[0]+dr, p[1]+dc) for p in prev_set}
            if shifted == cur_set:
                deltas.append(f"{colour}:({dr:+d},{dc:+d})")
                continue
        # Otherwise, list added / removed cells
        removed = prev_set - cur_set
        added = cur_set - prev_set
        parts = []
        if removed:
            parts.append("del" + "".join(f"({r},{c})" for r,c in sorted(removed)))
        if added:
            parts.append("add" + "".join(f"({r},{c})" for r,c in sorted(added)))
        deltas.append(f"{colour}:" + ";".join(parts))
    return "|".join(deltas) if deltas else "none"

